import math
from functools import reduce

alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def dist_search (mess):
    
    for i in range(len(mess) - 2):
        dist = []
        seq = mess [i:i+3]
        ind = 0 
        inst = 0
        for j in range(len(mess) - 2):
            seq2 = mess[j:j+3]
            if seq == seq2:
                inst += 1
                if j > 0:
                    dist.append(j - ind)
                ind = j
        if inst > 14 :
            return dist
    return dist

